/**
 * Relay client.
 *
 * The relay is an append-only log of opaque blobs per room. It has no accounts,
 * no read of the plaintext, and no way to tell one couple from another beyond a
 * random room id. `scripts/sync-worker/` is the Cloudflare Worker that serves
 * this contract on the free tier; the URL is a user setting precisely so anyone
 * can point it at their own.
 *
 * There is a **default relay** (`DEFAULT_RELAY`, set at build time), and there
 * is a reason that changed. The first version shipped none: pairing meant
 * deploying your own worker first, and the honest result was that almost
 * nobody got past that screen — a privacy property nobody reaches is not a
 * privacy property. The default is opt-in (nothing syncs until you pair), it
 * only ever receives ciphertext, and the field is still editable, so anyone
 * who wants to run their own still can with one command.
 */

import { SyncError, type Packet } from './packet'

export const NO_RELAY = ''

/**
 * Where pairing points when the user has not chosen a relay.
 *
 * Injected at build time (`TEMUDUA_RELAY`) rather than hard-coded, so a fork,
 * a self-hoster, and the published build are the same source with different
 * settings. Empty means "ask the user for one", which is exactly the old
 * behaviour — nothing about this build breaks when the value is absent.
 */
export const DEFAULT_RELAY: string = (import.meta.env?.VITE_RELAY_URL as string | undefined) ?? ''

export interface InviteBox {
  blob: string
}

/** Leaves the sealed pairing blob under its hash. */
export async function putInvite(
  relayUrl: string,
  hash: string,
  blob: string,
  signal?: AbortSignal,
): Promise<void> {
  await call(
    `${relayUrl}/i/${encodeURIComponent(hash)}`,
    { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ blob }) },
    signal,
  )
}

/**
 * Takes the blob and, by taking it, destroys it.
 *
 * A missing entry is the same answer for "never existed", "already claimed"
 * and "expired": the person typing has one thing to do about all three, which
 * is ask for a fresh code.
 */
export async function takeInvite(
  relayUrl: string,
  hash: string,
  signal?: AbortSignal,
): Promise<string> {
  let json: unknown
  try {
    json = await call(`${relayUrl}/i/${encodeURIComponent(hash)}`, { method: 'GET' }, signal)
  } catch (err) {
    if (err instanceof SyncError && err.message === 'relay 404') throw new SyncError('invite gone')
    throw err
  }
  const blob = (json as Partial<InviteBox>)?.blob
  if (typeof blob !== 'string' || !blob) throw new SyncError('invite gone')
  return blob
}

export interface PullResult {
  cursor: number
  packets: Packet[]
}

const MAX_BODY = 512 * 1024

interface Wire {
  cursor?: unknown
  items?: unknown
}

function isPacket(v: unknown): v is Packet & { seq: number } {
  const p = v as Partial<Packet>
  return typeof p?.iv === 'string' && typeof p?.ct === 'string'
}

async function call(url: string, init: RequestInit, signal?: AbortSignal): Promise<unknown> {
  let res: Response
  try {
    res = await fetch(url, { ...init, signal })
  } catch {
    // Offline is the normal case for a local-first app, not an exception.
    throw new SyncError('offline')
  }
  if (res.status === 413) throw new SyncError('too big')
  if (res.status === 429) throw new SyncError('rate limited')
  if (!res.ok) throw new SyncError(`relay ${res.status}`)
  try {
    return await res.json()
  } catch {
    throw new SyncError('relay reply')
  }
}

export async function push(
  relayUrl: string,
  roomId: string,
  packets: Packet[],
  signal?: AbortSignal,
): Promise<void> {
  if (packets.length === 0) return
  const body = JSON.stringify(packets)
  if (body.length > MAX_BODY) throw new SyncError('too big')
  await call(
    `${relayUrl}/r/${encodeURIComponent(roomId)}`,
    { method: 'POST', headers: { 'content-type': 'application/json' }, body },
    signal,
  )
}

export async function pull(
  relayUrl: string,
  roomId: string,
  since: number,
  signal?: AbortSignal,
): Promise<PullResult> {
  const json = (await call(
    `${relayUrl}/r/${encodeURIComponent(roomId)}?since=${since}`,
    { method: 'GET' },
    signal,
  )) as Wire
  const items = Array.isArray(json.items) ? json.items.filter(isPacket) : []
  const cursor = typeof json.cursor === 'number' ? json.cursor : since
  return { cursor, packets: items }
}
