/**
 * What actually crosses the network.
 *
 * Same shape as `security/crypto.ts`: Web Crypto AES-GCM, no dependency, no key
 * escrow. The difference is where the key comes from — a backup is unlocked by
 * a passphrase the user types, a sync room is unlocked by a 256-bit key that
 * only ever travels between the two phones as a QR code. The relay is handed
 * ciphertext against a random room id and can therefore learn nothing beyond
 * "somebody wrote N bytes to room X at time T".
 *
 * The room id is bound in as AES-GCM additional data, so a packet lifted from
 * one room cannot be replayed into another even by whoever runs the relay.
 */

import { z } from 'zod'
import { OWNED_STORES } from '@/db/db'
import type { Delta } from './syncMerge'

export const PAIRING_PREFIX = 'temudua-sync'
export const PAIRING_VERSION = '1'
const KEY_BYTES = 32
const IV_BYTES = 12
const ROOM_BYTES = 16

export class SyncError extends Error {}

// --- base64url ------------------------------------------------------------
// Plain base64 would put `+ / =` in the QR payload and in a URL path. base64url
// keeps both readable and copy-pasteable by hand when the camera will not focus.

function toB64u(bytes: ArrayBuffer | Uint8Array): string {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes)
  let s = ''
  for (const b of arr) s += String.fromCharCode(b)
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function fromB64u(s: string): Uint8Array {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/')
  let bin: string
  try {
    bin = atob(b64.padEnd(Math.ceil(b64.length / 4) * 4, '='))
  } catch {
    throw new SyncError('base64')
  }
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

export function randomRoomId(): string {
  return toB64u(crypto.getRandomValues(new Uint8Array(ROOM_BYTES)))
}

export function randomDeviceId(): string {
  // Six bytes is plenty to break clock ties, and short enough that the encoded
  // clock stays readable in a debug dump.
  return toB64u(crypto.getRandomValues(new Uint8Array(6)))
}

export async function generateRoomKey(): Promise<string> {
  const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, [
    'encrypt',
    'decrypt',
  ])
  return toB64u(await crypto.subtle.exportKey('raw', key))
}

export async function importRoomKey(keyB64: string): Promise<CryptoKey> {
  const raw = fromB64u(keyB64)
  if (raw.length !== KEY_BYTES) throw new SyncError('key length')
  return crypto.subtle.importKey('raw', raw as BufferSource, 'AES-GCM', false, [
    'encrypt',
    'decrypt',
  ])
}

// --- packets --------------------------------------------------------------

export interface Packet {
  iv: string
  ct: string
}

export async function seal(key: CryptoKey, roomId: string, deltas: Delta[]): Promise<Packet> {
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES))
  const ct = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: iv as BufferSource, additionalData: new TextEncoder().encode(roomId) },
    key,
    new TextEncoder().encode(JSON.stringify(deltas)),
  )
  return { iv: toB64u(iv), ct: toB64u(ct) }
}

/**
 * Field names are restricted to plain identifiers. Domain fields all look like
 * that, and it is the cheapest way to make `__proto__` unreachable in the
 * object `materialize()` builds by assignment.
 */
const FIELD_NAME = /^[a-zA-Z][a-zA-Z0-9_]{0,40}$/

/**
 * Checked against the raw JSON, before the schema runs.
 *
 * Deliberately not left to zod's key schema: a record whose key fails
 * validation is *dropped* rather than rejected, and a field that vanishes
 * silently is exactly the failure mode a merge engine must never have. A
 * hostile name is a reason to throw the whole packet away, not to quietly
 * deliver the rest of it.
 */
function assertFieldNames(json: unknown): void {
  if (!Array.isArray(json)) throw new SyncError('shape')
  for (const delta of json) {
    const fields = (delta as { fields?: unknown })?.fields
    if (fields === undefined) continue
    if (typeof fields !== 'object' || fields === null || Array.isArray(fields)) {
      throw new SyncError('shape')
    }
    for (const name of Object.keys(fields)) {
      if (!FIELD_NAME.test(name)) throw new SyncError('field name')
    }
  }
}

const deltaSchema = z.object({
  store: z.enum(OWNED_STORES as unknown as [string, ...string[]]),
  id: z.string().min(1).max(200),
  fields: z.record(z.string(), z.object({ v: z.unknown(), c: z.string().min(3) })),
  tombstone: z.string().min(3).optional(),
})

const payloadSchema = z.array(deltaSchema).max(5000)

/**
 * Decrypts and validates. A packet that fails either is skipped, never fatal:
 * the room may legitimately contain packets from an older app version, and one
 * bad packet must not wedge sync forever.
 */
export async function open(key: CryptoKey, roomId: string, pkt: Packet): Promise<Delta[]> {
  let plain: ArrayBuffer
  try {
    plain = await crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv: fromB64u(pkt.iv) as BufferSource,
        additionalData: new TextEncoder().encode(roomId),
      },
      key,
      fromB64u(pkt.ct) as BufferSource,
    )
  } catch {
    throw new SyncError('decrypt')
  }
  let json: unknown
  try {
    json = JSON.parse(new TextDecoder().decode(plain))
  } catch {
    throw new SyncError('json')
  }
  assertFieldNames(json)
  const parsed = payloadSchema.safeParse(json)
  if (!parsed.success) throw new SyncError('shape')
  return parsed.data as Delta[]
}

// --- pairing code ---------------------------------------------------------

export interface Pairing {
  roomId: string
  keyB64: string
  /** Where the two devices meet. There is no default — see relay.ts. */
  relayUrl: string
}

/**
 * `temudua-sync/1/<room>/<key>/<relay>`.
 *
 * A slash-separated string rather than a URL with query parameters: it is
 * shorter (a smaller QR, which matters when the other phone's camera is
 * focusing on a screen) and it has no scheme a browser might try to open.
 */
export function encodePairing(p: Pairing): string {
  return [PAIRING_PREFIX, PAIRING_VERSION, p.roomId, p.keyB64, toB64u(new TextEncoder().encode(p.relayUrl))].join(
    '/',
  )
}

export function assertRelayUrl(raw: string): string {
  let url: URL
  try {
    url = new URL(raw.trim())
  } catch {
    throw new SyncError('relay url')
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new SyncError('relay scheme')
  return url.toString().replace(/\/+$/, '')
}

export function parsePairing(text: string): Pairing {
  const parts = text.trim().split('/')
  if (parts.length !== 5 || parts[0] !== PAIRING_PREFIX) throw new SyncError('pairing format')
  if (parts[1] !== PAIRING_VERSION) throw new SyncError('pairing version')
  const [, , roomId = '', keyB64 = '', relay = ''] = parts
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(roomId)) throw new SyncError('room id')
  if (fromB64u(keyB64).length !== KEY_BYTES) throw new SyncError('key length')
  return { roomId, keyB64, relayUrl: assertRelayUrl(new TextDecoder().decode(fromB64u(relay))) }
}
