import { useMemo } from 'react'
import { encodeQr } from './qr'

const QUIET = 4 // modules of margin; the spec's minimum, and scanners rely on it

/**
 * Renders the module grid as a single `<path>` with horizontal runs merged.
 * A version-7 code is 45×45; one `<rect>` per dark module would be roughly a
 * thousand DOM nodes for a picture that never changes.
 */
export function QrCode({ text, label }: { text: string; label: string }) {
  const d = useMemo(() => {
    const modules = encodeQr(text)
    const parts: string[] = []
    for (let r = 0; r < modules.length; r++) {
      const row = modules[r]!
      let c = 0
      while (c < row.length) {
        if (!row[c]) {
          c++
          continue
        }
        let run = 1
        while (row[c + run]) run++
        parts.push(`M${c + QUIET} ${r + QUIET}h${run}v1h-${run}z`)
        c += run
      }
    }
    return { path: parts.join(''), size: modules.length + QUIET * 2 }
  }, [text])

  return (
    <svg
      className="qr"
      viewBox={`0 0 ${d.size} ${d.size}`}
      role="img"
      aria-label={label}
      shapeRendering="crispEdges"
    >
      <rect width={d.size} height={d.size} fill="#fff" />
      <path d={d.path} fill="#000" />
    </svg>
  )
}
