/**
 * Two-device sync — the merge core.
 *
 * Pure functions only: no Dexie, no fetch, no strings the user ever sees. Every
 * decision about "which write wins" lives here so it can be proven in a test
 * instead of argued about.
 *
 * Three rules, in order:
 *
 * 1. **Only shared records exist here at all.** `scanLocal` is the one and only
 *    producer of outbound deltas, and it drops anything that is not `shared` or
 *    `both_partners` before it looks at the body. A private row cannot reach the
 *    outbox because there is no code path that puts it there — see
 *    `syncMerge.test.ts`.
 * 2. **Per-field last-write-wins on a hybrid logical clock.** Each field carries
 *    its own clock, so two phones editing two different fields of the same row
 *    both keep their write. A phone whose wall clock is an hour behind still
 *    sorts after anything it has already seen, because receiving a remote clock
 *    drags the local one forward (`hlcRecv`).
 * 3. **Tombstones are absorbing.** Once a record is deleted, no edit revives it,
 *    whichever order the two devices happen to see the packets in. That is what
 *    makes "delete beats a concurrent edit" true in both directions rather than
 *    only in the lucky one.
 */

import type { OwnedStore } from '@/db/db'
import type { Envelope, Visibility } from '@/types/domain'

// ---------------------------------------------------------------------------
// Hybrid logical clock
// ---------------------------------------------------------------------------

export interface Hlc {
  /** Wall clock, ms since epoch. Advisory — it is never trusted on its own. */
  wall: number
  counter: number
  /** Random per-device id. Breaks ties so both phones pick the same winner. */
  node: string
}

/**
 * Encoded clock. Fixed-width wall and counter mean plain string comparison is
 * the clock comparison — no parsing on the hot path, and it survives JSON.
 */
export type Clock = string

const WALL_DIGITS = 14 // ms since epoch needs 13; 14 lasts past the year 5138
const COUNTER_DIGITS = 4
const MAX_COUNTER = 10 ** COUNTER_DIGITS - 1

export function encodeHlc(h: Hlc): Clock {
  return `${String(h.wall).padStart(WALL_DIGITS, '0')}.${String(h.counter).padStart(
    COUNTER_DIGITS,
    '0',
  )}.${h.node}`
}

export function decodeHlc(c: Clock): Hlc {
  const [wall = '0', counter = '0', ...rest] = c.split('.')
  return { wall: Number(wall), counter: Number(counter), node: rest.join('.') }
}

function bump(wall: number, counter: number): { wall: number; counter: number } {
  // Only reachable if a device emits 10 000 events inside one millisecond.
  return counter > MAX_COUNTER ? { wall: wall + 1, counter: 0 } : { wall, counter }
}

/** Clock for a local event. */
export function hlcSend(prev: Hlc, wallNow: number): Hlc {
  const wall = Math.max(prev.wall, wallNow)
  return { ...bump(wall, wall === prev.wall ? prev.counter + 1 : 0), node: prev.node }
}

/**
 * Clock after seeing a remote event. This is the whole point of the hybrid
 * clock: a phone that is behind adopts the remote wall time, so its *next*
 * local write is ordered after the write it just read instead of silently
 * landing in the past and losing.
 */
export function hlcRecv(prev: Hlc, remote: Hlc, wallNow: number): Hlc {
  const wall = Math.max(prev.wall, remote.wall, wallNow)
  let counter = 0
  if (wall === prev.wall && wall === remote.wall) counter = Math.max(prev.counter, remote.counter) + 1
  else if (wall === prev.wall) counter = prev.counter + 1
  else if (wall === remote.wall) counter = remote.counter + 1
  return { ...bump(wall, counter), node: prev.node }
}

/**
 * A device's clock, as an object rather than a bare `() => Clock`.
 *
 * The extra method is the important one. Last-write-wins is only safe while a
 * new write is guaranteed to dominate the value it replaces, so every clock
 * this device *observes* — a remote delta, or the shadow entry it is about to
 * overwrite — has to push the local clock forward first. Handing callers a
 * plain `next()` made that a convention someone would eventually forget;
 * `observe()` makes it something the merge core does for itself.
 */
export interface ClockSource {
  /** A clock strictly greater than everything observed so far. */
  next(): Clock
  /** Note that `c` exists. Later `next()` calls will beat it. */
  observe(c: Clock): void
  /** Current position, for persisting across app restarts. */
  peek(): Clock
}

export function makeClock(node: string, seed?: Clock, wall: () => number = Date.now): ClockSource {
  let h: Hlc = seed ? { ...decodeHlc(seed), node } : { wall: wall(), counter: 0, node }
  return {
    next: () => {
      h = hlcSend(h, wall())
      return encodeHlc(h)
    },
    observe: (c) => {
      h = hlcRecv(h, decodeHlc(c), wall())
    },
    peek: () => encodeHlc(h),
  }
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

/** `null` means "field cleared" — JSON has no undefined, and the domain has no real nulls. */
export interface FieldValue {
  v: unknown
  c: Clock
}

export interface RecordState {
  store: OwnedStore
  fields: Record<string, FieldValue>
  /** Set once, never unset. A tombstoned record carries no fields. */
  tombstone?: Clock
}

/** The sync shadow: what this device believes both devices agree on. */
export type SyncState = Record<string, RecordState>

export interface Delta {
  store: OwnedStore
  id: string
  fields: Record<string, FieldValue>
  tombstone?: Clock
}

export const keyOf = (store: OwnedStore, id: string): string => `${store}/${id}`
export const idOf = (key: string): string => key.slice(key.indexOf('/') + 1)

// ---------------------------------------------------------------------------
// The privacy gate
// ---------------------------------------------------------------------------

/**
 * The only two visibility states that may leave the device. `self_reflection`
 * and `share_later` are deliberately excluded: a draft the owner has not
 * released is not a share, and neither is a note they keep for themselves.
 */
const SYNCABLE: ReadonlySet<Visibility> = new Set<Visibility>(['shared', 'both_partners'])

export function isSyncable(env: Pick<Envelope, 'visibility' | 'deletedAt'>): boolean {
  return !env.deletedAt && SYNCABLE.has(env.visibility)
}

// ---------------------------------------------------------------------------
// Local scan → outbound deltas
// ---------------------------------------------------------------------------

export interface LocalRow {
  store: OwnedStore
  row: Envelope & Record<string, unknown>
}

export interface ScanResult {
  state: SyncState
  deltas: Delta[]
}

/** undefined and null are the same thing on the wire: "this field is not set". */
function normalise(v: unknown): unknown {
  return v === undefined ? null : v
}

/**
 * Structural equality over JSON-shaped domain values. Every syncable field is a
 * string, number, boolean, string[], or a small flat object (`recurrence`,
 * `splitShares`, `agenda`), so serialising is both correct and cheap here.
 */
function sameValue(a: unknown, b: unknown): boolean {
  return a === b || JSON.stringify(a) === JSON.stringify(b)
}

/**
 * Diffs the readable-and-syncable rows against the shadow and returns the
 * deltas that need to go out.
 *
 * `rows` must be everything this profile can read *right now*. A row that is
 * missing from it — deleted, or un-shared back to private — becomes a
 * tombstone, which is how a retraction reaches the other phone without ever
 * shipping the body of a record that is no longer shared.
 *
 * A changed record ships **all** of its fields, each with its own clock, not
 * just the changed ones. Unchanged fields keep their old clock so they lose
 * cleanly against a newer remote write; shipping them anyway means a device
 * that missed a packet heals on the next sync instead of staying half-updated.
 */
export function scanLocal(state: SyncState, rows: LocalRow[], clock: ClockSource): ScanResult {
  let next = state
  const deltas: Delta[] = []
  const present = new Set<string>()

  for (const { store, row } of rows) {
    // The gate. Nothing below this line runs for a private record, so there is
    // no branch anywhere that could leak one.
    if (!isSyncable(row)) continue

    const key = keyOf(store, row.id)
    present.add(key)
    const prev = next[key]
    if (prev?.tombstone) continue // deletion is terminal

    // Every clock we might overwrite, before minting a single new one.
    for (const f of Object.values(prev?.fields ?? {})) clock.observe(f.c)

    const fields: Record<string, FieldValue> = {}
    let changed = prev === undefined
    const names = new Set([...Object.keys(row), ...Object.keys(prev?.fields ?? {})])
    for (const name of names) {
      if (name === 'id') continue // the delta key already carries it
      const value = normalise(row[name])
      const before = prev?.fields[name]
      if (before && sameValue(before.v, value)) {
        fields[name] = before
        continue
      }
      fields[name] = { v: value, c: clock.next() }
      changed = true
    }
    if (!changed) continue
    next = { ...next, [key]: { store, fields } }
    deltas.push({ store, id: row.id, fields })
  }

  for (const [key, rec] of Object.entries(next)) {
    if (present.has(key) || rec.tombstone) continue
    for (const f of Object.values(rec.fields)) clock.observe(f.c)
    const tombstone = clock.next()
    next = { ...next, [key]: { store: rec.store, fields: {}, tombstone } }
    deltas.push({ store: rec.store, id: idOf(key), fields: {}, tombstone })
  }

  return { state: next, deltas }
}

// ---------------------------------------------------------------------------
// Merge
// ---------------------------------------------------------------------------

/**
 * Two tombstones for the same record settle on the earlier clock. Any
 * deterministic pick works; taking the minimum means the result does not depend
 * on which packet landed first.
 */
function pickTombstone(a: Clock | undefined, b: Clock | undefined): Clock {
  if (a === undefined) return b as Clock
  if (b === undefined) return a
  return a < b ? a : b
}

/** Folds one delta into the shadow. Pure, idempotent, and order-independent. */
export function mergeDelta(state: SyncState, delta: Delta): SyncState {
  const key = keyOf(delta.store, delta.id)
  const prev = state[key]

  if (prev?.tombstone !== undefined || delta.tombstone !== undefined) {
    const tombstone = pickTombstone(prev?.tombstone, delta.tombstone)
    if (prev?.tombstone === tombstone) return state
    return { ...state, [key]: { store: delta.store, fields: {}, tombstone } }
  }

  const fields = { ...(prev?.fields ?? {}) }
  let changed = prev === undefined
  for (const [name, f] of Object.entries(delta.fields)) {
    const cur = fields[name]
    // `>=` and not `>`: equal clocks mean the same event, so keep what we have.
    if (cur && cur.c >= f.c) continue
    fields[name] = f
    changed = true
  }
  return changed ? { ...state, [key]: { store: delta.store, fields } } : state
}

export function mergeAll(state: SyncState, deltas: readonly Delta[]): SyncState {
  return deltas.reduce(mergeDelta, state)
}

/**
 * Rebuilds the row a record's fields describe, or `undefined` when it has been
 * tombstoned — the caller soft-deletes in that case rather than writing a husk.
 */
export function materialize(state: SyncState, key: string): Record<string, unknown> | undefined {
  const rec = state[key]
  if (!rec || rec.tombstone !== undefined) return undefined
  const out: Record<string, unknown> = { id: idOf(key) }
  for (const [name, f] of Object.entries(rec.fields)) {
    if (f.v !== null) out[name] = f.v
  }
  return out
}

/** The highest clock any incoming delta carries — used to advance the local HLC. */
export function highestClock(deltas: readonly Delta[]): Clock | undefined {
  let top: Clock | undefined
  for (const d of deltas) {
    for (const f of Object.values(d.fields)) if (top === undefined || f.c > top) top = f.c
    if (d.tombstone !== undefined && (top === undefined || d.tombstone > top)) top = d.tombstone
  }
  return top
}
